<?php /** DESIGN REMINDER: Collector's Folio — clear editorial fallback templates, always preserve WordPress content and accessibility. */ get_header(); ?>
<main class="archive-main"><header class="archive-heading"><p class="eyebrow eyebrow--ink"><i></i><?php esc_html_e( 'The atelier journal', 'uniqueperspective8' ); ?></p><h1><?php single_post_title(); ?></h1></header><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); ?><article <?php post_class( 'journal-post' ); ?>><p class="small-label"><?php echo esc_html( get_the_date() ); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div><?php the_excerpt(); ?></div><a class="text-link text-link--ink" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Read entry', 'uniqueperspective8' ); ?> <span>↗</span></a></article><?php endwhile; the_posts_pagination(); else : ?><p><?php esc_html_e( 'No entries are available yet.', 'uniqueperspective8' ); ?></p><?php endif; ?></main><?php get_footer(); ?>
